class Solution:
    def canBeTypedWords(self, text: str, brokenLetters: str) -> int:
        lookup = set(brokenLetters)
        result, broken = 0, False
        for c in text:
            if c == ' ':
                result += int(broken == False)
                broken = False
            elif c in lookup:
                broken = True
        return result + int(broken == False)

